detaileddescription.para:
Example usage: OperatorDiagnosticsdiagnostics;

//Detectcoordinatortimeoutpattern
ErrorContextctx;
ctx.error_code=DiagnosticErrorCode::COORDINATION_TIMEOUT;
ctx.operation="coordinate_update";

autoscenario=diagnostics.detectScenario(ctx);
if(scenario==FailureScenario::COORDINATOR_UNREACHABLE){
autoprocedure=diagnostics.getRecoveryProcedure(scenario);
std::cout<<"Recoverysteps:"<<std::endl;
for(constauto&step:procedure.recovery_steps){
std::cout<<"-"<<step<<std::endl;
}
}

//Generatealertingrulesforobservabilitytools
autorules=diagnostics.getAllAlertingRules();
for(constauto&rule:rules){
std::cout<<rule.rule_name<<":"<<rule.condition<<std::endl;
}
